/* ======================================================================
   Modèle
   item.type : paragraphe | texte | nombre | liste | ouinon | prixlibre
   réponse   : { label, mode:"montant"|"fonction", val, fn }
   fn        : { type:"mult", src:"cle", k:9.5 }
             | { type:"bareme", src:"cle", vals:[...] }   (aligné sur les réponses de la source)
             | { type:"expr", expr:"effectif * 30" }
   ====================================================================== */
const TYPES = [["liste","Liste déroulante"],["ouinon","Oui / Non"],["nombre","Nombre"],["texte","Texte"],["prixlibre","Prix libre"],["paragraphe","Paragraphe"]];
const PERS = [["mensuelle","Mensuelle"],["annuelle","Annuelle"],["ponctuelle","Ponctuelle"]];
const CATS = ["Comptabilité","Fiscalité","Gestion","Juridique","Social","Présentation"];
const FN_TYPES = [["mult","Champ × multiplicateur"],["bareme","Barème par réponse"],["expr","Expression"]];

const R  = (label, val=0) => ({ id:uid(), label, clientLabel:"", mode:"montant", val:+val||0, fn:null, n:null });
const RM = (label, src, k) => ({ id:uid(), label, clientLabel:"", mode:"fonction", val:0, fn:{type:"mult",src,k}, n:null });
const RB = (label, src, vals) => ({ id:uid(), label, clientLabel:"", mode:"fonction", val:0, fn:{type:"bareme",src,vals}, n:null });
const I  = (label, type, o={}) => Object.assign({ id:uid(), cle:slug(label), label, type, per:"mensuelle", tva:20, prix:true, aide:"", clientText:"", reponses:[], fn:null, html:"" }, o);
const SEC = (titre, tag, items) => ({ id:uid(), titre, tag, items });

/* Volumétries : n = valeur numérique exploitable par les expressions.
   Les barèmes s'appuient sur l'ordre des réponses, pas sur n. */
const CA   = ["À renseigner","<100 K€","100 K€ <> 200 K€","200 K€ <> 300 K€","300 K€ <> 500 K€","500 K€ <> 800 K€","800 K€ <> 1.000 K€","1 M€ <> 1,5 M€","1,5 M€ <> 3 M€","3 M€ <> 5 M€","> 5 M€"];
const CA_N = [0,100000,200000,300000,500000,800000,1000000,1500000,3000000,5000000,8000000];
const FACT   = ["<5","5 <> 10","10 <> 20","20 <> 40","40 <> 70","70 <> 100","100 <> 150","> 150","NA"];
const FACT_N = [3,7,15,30,55,85,125,180,0];
